<?php namespace App\Http\Controllers;
use App\Models\Farm; use Illuminate\Http\Request;
class FarmController extends Controller { public function index(){return view('farm.index',['farms'=>Farm::latest()->paginate(15)]);} public function create(){return view('farm.form',['farm'=>new Farm]);} public function store(Request $r){$d=$r->validate(['name'=>'required','owner'=>'nullable','commodity'=>'nullable','area'=>'nullable|numeric','latitude'=>'required|numeric','longitude'=>'required|numeric','status'=>'required']); Farm::create($d); return redirect()->route('farms.index')->with('ok','Lahan berhasil ditambahkan.');} public function show(Farm $farm){return view('farm.show',compact('farm'));} public function edit(Farm $farm){return view('farm.form',compact('farm'));} public function update(Request $r,Farm $farm){$farm->update($r->validate(['name'=>'required','owner'=>'nullable','commodity'=>'nullable','area'=>'nullable|numeric','latitude'=>'required|numeric','longitude'=>'required|numeric','status'=>'required'])); return redirect()->route('farms.index')->with('ok','Data diperbarui.');} public function destroy(Farm $farm){$farm->delete();return back();} }
